for p in paths:
 d=Document(p); out[os.path.basename(p)]={"paragraphs":[x.text for x in d.paragraphs if x.text.strip()],"tables":[[[c.text for c in r.cells] for r in t.rows] for t in d.tables]}
w=load_workbook("/documents/付款退款明细.xlsx",data_only=False); out["xlsx"]={}
for s in w:
 out["xlsx"][s.title]=[[c.value.isoformat() if hasattr(c.value,"isoformat") else c.value for c in row] for row in s.iter_rows() if any(c.value is not None for c in row)]
print(json.dumps(out,ensure_ascii=False,indent=2))'
